using System.ComponentModel;
using System.Windows;
using System.Windows.Controls;
using UserControl=System.Windows.Controls.UserControl;
using Button=System.Windows.Controls.Button;
using SystemColors=System.Windows.SystemColors;
using ClipSync.Windows.MainUI.ViewModels;
namespace ClipSync.Windows.MainUI.Pages.Onboarding;
public partial class OnboardingPage : UserControl, IDisposable
{
 readonly OnboardingViewModel viewModel; readonly Action helpRequested; bool disposed;
 public OnboardingPage(ShellViewModel shell,Action done,Action skipped,Action help){InitializeComponent();helpRequested=help;viewModel=new OnboardingViewModel(shell);DataContext=viewModel;PairingPanel.DataContext=viewModel.Pairing;AdditionalPairingPanel.DataContext=viewModel.Pairing;viewModel.DoneRequested+=done;viewModel.SkipRequested+=skipped;viewModel.PropertyChanged+=ViewModelChanged;SizeChanged+=ResponsiveLayout;Loaded+=(_,_)=>{ResponsiveLayout(this,EventArgs.Empty);ApplyPairingPalette();ApplyHighContrast();};UpdateActionLabel();}
 void ViewModelChanged(object? sender,PropertyChangedEventArgs e){if(e.PropertyName==nameof(OnboardingViewModel.Step)){UpdateActionLabel();if(SystemParameters.ClientAreaAnimation)StepContent.BeginAnimation(OpacityProperty,new System.Windows.Media.Animation.DoubleAnimation(.35,1,TimeSpan.FromMilliseconds(180)));}else if(e.PropertyName==nameof(OnboardingViewModel.ShowPairingPanel))Dispatcher.BeginInvoke(new Action(ApplyPairingPalette));}
 void UpdateActionLabel(){NextButton.Content=viewModel.Step==0?"Get started":viewModel.Step==4?"Finish":"Continue";System.Windows.Automation.AutomationProperties.SetName(NextButton,NextButton.Content.ToString());}
 void ResponsiveLayout(object? sender,EventArgs e){if(ContentGrid is null)return;var stacked=ActualWidth<860;var stepPanel=(ItemsPanelTemplate)FindResource(stacked?"HorizontalStepsPanel":"VerticalStepsPanel");Stepper.ItemsPanel=stepPanel;if(stacked){ContentGrid.ColumnDefinitions[0].Width=new GridLength(1,GridUnitType.Star);ContentGrid.ColumnDefinitions[1].Width=new GridLength(0);ContentGrid.ColumnDefinitions[2].Width=new GridLength(0);ContentGrid.RowDefinitions.Clear();ContentGrid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});ContentGrid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});Grid.SetRow(StepperRegion,0);Grid.SetColumn(StepperRegion,0);Grid.SetRowSpan(StepperRegion,1);Grid.SetColumnSpan(StepperRegion,1);Grid.SetRow(RightColumn,1);Grid.SetColumn(RightColumn,0);Grid.SetColumnSpan(RightColumn,1);StepperRegion.Padding=new Thickness(0,8,0,8);StepperRegion.Background=System.Windows.Media.Brushes.Transparent;StepperRegion.BorderThickness=new Thickness(0,0,0,1);RailIntro.Visibility=Visibility.Collapsed;RailFooter.Visibility=Visibility.Collapsed;LeftColumn.Margin=new Thickness(0,16,0,16);foreach(var connector in Descendants<Border>(Stepper).Where(x=>x.Name=="StepConnector"))connector.Visibility=Visibility.Collapsed;}else{ContentGrid.ColumnDefinitions[0].Width=new GridLength(224);ContentGrid.ColumnDefinitions[1].Width=new GridLength(32);ContentGrid.ColumnDefinitions[2].Width=new GridLength(1,GridUnitType.Star);ContentGrid.RowDefinitions.Clear();ContentGrid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});Grid.SetRow(StepperRegion,0);Grid.SetColumn(StepperRegion,0);Grid.SetRowSpan(StepperRegion,1);Grid.SetColumnSpan(StepperRegion,1);Grid.SetRow(RightColumn,0);Grid.SetColumn(RightColumn,2);Grid.SetColumnSpan(RightColumn,1);StepperRegion.Padding=new Thickness(16,24,16,24);StepperRegion.Background=(System.Windows.Media.Brush)FindResource("Surface");StepperRegion.BorderThickness=new Thickness(0,0,1,0);RailIntro.Visibility=Visibility.Visible;RailFooter.Visibility=Visibility.Visible;LeftColumn.Margin=new Thickness(0,0,0,16);foreach(var connector in Descendants<Border>(Stepper).Where(x=>x.Name=="StepConnector"))connector.Visibility=Visibility.Visible;}}
 void Troubleshooting_Click(object sender,RoutedEventArgs e)=>helpRequested();
 void ApplyPairingPalette(){var fg=(System.Windows.Media.Brush)FindResource("GuideText");var bg=(System.Windows.Media.Brush)FindResource("GuideSurface");var line=(System.Windows.Media.Brush)FindResource("GuideLine");var accent=(System.Windows.Media.Brush)FindResource("GuideAccent");var onAccent=(System.Windows.Media.Brush)FindResource("GuideAccentText");foreach(var panel in new[]{PairingPanel,AdditionalPairingPanel}){foreach(var text in Descendants<TextBlock>(panel))text.Foreground=fg;foreach(var border in Descendants<Border>(panel)){border.Background=bg;border.BorderBrush=line;}foreach(var path in Descendants<System.Windows.Shapes.Path>(panel))path.Stroke=accent;foreach(var button in Descendants<Button>(panel)){var primary=button.Content is string label&&label is "Generate code" or "Regenerate";button.Background=primary?accent:bg;button.Foreground=primary?onAccent:fg;button.BorderBrush=primary?accent:line;}}}
 void ApplyHighContrast(){if(!SystemParameters.HighContrast)return;RootGrid.Background=SystemColors.WindowBrush;foreach(var t in Descendants<TextBlock>(RootGrid))t.Foreground=SystemColors.WindowTextBrush;foreach(var p in Descendants<System.Windows.Shapes.Path>(RootGrid))p.Stroke=SystemColors.WindowTextBrush;foreach(var b in Descendants<Button>(RootGrid)){b.Foreground=SystemColors.WindowTextBrush;b.BorderBrush=SystemColors.WindowTextBrush;b.Background=SystemColors.ControlBrush;}foreach(var border in Descendants<Border>(RootGrid)){border.BorderBrush=SystemColors.WindowTextBrush;border.Background=SystemColors.WindowBrush;}}
 static System.Collections.Generic.IEnumerable<T> Descendants<T>(DependencyObject root) where T:DependencyObject{for(var i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++){var child=System.Windows.Media.VisualTreeHelper.GetChild(root,i);if(child is T t)yield return t;foreach(var nested in Descendants<T>(child))yield return nested;}}
 public void Dispose(){if(disposed)return;disposed=true;viewModel.PropertyChanged-=ViewModelChanged;viewModel.Dispose();}
}
